queries.query:
PREFIX agents: <https://data.oireachtas.ie/ontology#>
PREFIX foaf: <http://xmlns.com/foaf/0.1/>
SELECT DISTINCT ?entity ?label WHERE {
  GRAPH ?entityGraph { ?entity a agents:Member ; <http://xmlns.com/foaf/0.1/name> ?label . }
  FILTER(STRSTARTS(STR(?entityGraph), "https://data.oireachtas.ie/graph/member/"))
  FILTER(CONTAINS(LCASE(STR(?label)), LCASE(STR("Mary Lou McDonald"))))
}
LIMIT 100

PREFIX members: <https://data.oireachtas.ie/ontology/members#>
SELECT DISTINCT ?term WHERE {
 GRAPH ?g { <https://data.oireachtas.ie/ie/oireachtas/member/id/Mary-Lou-McDonald.D.2011-03-09> members:hasMembersMembership ?membership .
 ?membership a members:DailMembership ; members:inHouseTerm ?term . }
 FILTER(STRSTARTS(STR(?g), "https://data.oireachtas.ie/graph/member/"))
} ORDER BY ?term

